import csv
from collections import defaultdict

ts_map = {
 'Perimeter_ZN_1': 'd68b2820-900f-5e5f-bea4-9d92f2f106df',
 'Perimeter_ZN_2': 'fb91b6fa-b336-5d94-a6fe-e00343bc30a9',
}
id2zone = {v:k for k,v in ts_map.items()}
zone = {k:[] for k in ts_map}

with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        ts = row['timeseries_id']
        if ts in id2zone:
            z = id2zone[ts]
            ts2 = row['timestamp']
            if ts2.startswith('2018-01-11'):
                hm = ts2[11:16]
                if hm >= '08:00' and hm <= '18:00':
                    zone[z].append(float(row['value']))

m1 = sum(zone['Perimeter_ZN_1'])/len(zone['Perimeter_ZN_1'])
m2 = sum(zone['Perimeter_ZN_2'])/len(zone['Perimeter_ZN_2'])
print(len(zone['Perimeter_ZN_1']), len(zone['Perimeter_ZN_2']))
print(zone['Perimeter_ZN_1'])
print(zone['Perimeter_ZN_2'])
print("mean1", m1, "mean2", m2)
print("diff", m1-m2)
